package com.auth.server.repository;

import com.auth.server.model.Token;
import com.auth.server.model.Token.TokenType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

public interface TokenRepository extends JpaRepository<Token, String> {

    // Find token by token value
    Optional<Token> findByTokenValue(String tokenValue);

    // Find all tokens for a user
    List<Token> findByUserId(String userId);

    // Find by token type and user
    List<Token> findByUserIdAndTokenType(String userId, TokenType tokenType);

    // Find revoked tokens
    List<Token> findByIsRevokedTrue();

    // Find consumed tokens
    List<Token> findByIsConsumedTrue();

    // Find expired tokens (using native query for efficiency)
    @Query("SELECT t FROM Token t WHERE t.expiresAt < :now AND t.isRevoked = false AND t.isConsumed = false")
    List<Token> findExpiredTokens(@Param("now") Instant now);

    // Find revoked tokens that are not consumed
    @Query("SELECT t FROM Token t WHERE t.isRevoked = true AND t.isConsumed = false")
    List<Token> findRevokedTokens();

    // Find consumed tokens that are not revoked  
    @Query("SELECT t FROM Token t WHERE t.isConsumed = true AND t.isRevoked = false")
    List<Token> findConsumedTokens();

    // Check if token exists and is valid (not expired, not revoked, not consumed)
    @Query("SELECT t FROM Token t WHERE t.tokenValue = :tokenValue AND t.expiresAt > :now AND t.isRevoked = false AND t.isConsumed = false")
    Optional<Token> findValidToken(@Param("tokenValue") String tokenValue, @Param("now") Instant now);

    // Count tokens for deletion logic
    @Query("SELECT COUNT(t) FROM Token t WHERE (t.expiresAt < :now OR t.isRevoked = true OR t.isConsumed = true) AND t.isRevoked = false AND t.isConsumed = false")
    long countTokensToDelete(@Param("now") Instant now);

    // Atomic operations for refresh token rotation
    @Modifying
    @Transactional
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.tokenValue = :tokenValue")
    int revokeTokenByValue(@Param("tokenValue") String tokenValue);

    // Atomic update to mark token as consumed
    @Modifying
    @Transactional
    @Query("UPDATE Token t SET t.isConsumed = true WHERE t.tokenValue = :tokenValue")
    int consumeTokenByValue(@Param("tokenValue") String tokenValue);

    // Delete expired, revoked, or consumed tokens
    @Modifying
    @Transactional
    @Query("DELETE FROM Token t WHERE (t.expiresAt < :now OR t.isRevoked = true OR t.isConsumed = true) AND t.isRevoked = false AND t.isConsumed = false")
    int deleteTokensToDelete(@Param("now") Instant now);
}
