package com.auth.server.service;

import com.auth.server.model.Token;
import com.auth.server.model.Token.TokenType;
import com.auth.server.repository.TokenRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.UUID;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;

    @Autowired
    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    /**
     * Login - issues all three tokens atomically
     */
    @Transactional
    public LoginResponse login(String username, String password) {
        // For this system, we accept any non-empty username/password
        // We use username as user identifier
        String userId = username; // Simplified: username = user_id

        Instant now = Instant.now();
        Instant accessTokenExpires = now.plus(10, ChronoUnit.MINUTES);
        Instant refreshTokenExpires = now.plus(24, ChronoUnit.HOURS);
        Instant oneTimeTokenExpires = now.plus(5, ChronoUnit.MINUTES);

        // Generate tokens (UUIDs)
        String accessToken = UUID.randomUUID().toString();
        String refreshToken = UUID.randomUUID().toString();
        String oneTimeToken = UUID.randomUUID().toString();

        // Create and save all tokens in one transaction
        Token accessTokenToken = new Token(accessToken, userId, TokenType.ACCESS_TOKEN, now, accessTokenExpires);
        Token refreshTokenToken = new Token(refreshToken, userId, TokenType.REFRESH_TOKEN, now, refreshTokenExpires);
        Token oneTimeTokenToken = new Token(oneTimeToken, userId, TokenType.ONE_TIME_TOKEN, now, oneTimeTokenExpires);

        tokenRepository.save(accessTokenToken);
        tokenRepository.save(refreshTokenToken);
        tokenRepository.save(oneTimeTokenToken);

        return new LoginResponse(accessToken, refreshToken, oneTimeToken, userId);
    }

    /**
     * Renew access token using refresh token
     * Implements refresh token rotation
     */
    @Transactional
    public RenewResponse renew(String refreshTokenValue) {
        Instant now = Instant.now();

        // Find the refresh token
        Token oldRefreshToken = tokenRepository.findByTokenValue(refreshTokenValue)
            .orElseThrow(() -> new RuntimeException("Refresh token not found"));

        // Check if valid: not expired, not revoked, not consumed
        if (oldRefreshToken.getExpiresAt().isBefore(now)) {
            throw new RuntimeException("Refresh token expired");
        }
        if (oldRefreshToken.isRevoked()) {
            throw new RuntimeException("Refresh token revoked");
        }
        if (oldRefreshToken.isConsumed()) {
            throw new RuntimeException("Refresh token already used");
        }

        // Get user ID
        String userId = oldRefreshToken.getUserId();

        // Revoke the old refresh token atomically
        tokenRepository.revokeTokenByValue(refreshTokenValue);

        // Issue new tokens
        String newAccessToken = UUID.randomUUID().toString();
        String newRefreshToken = UUID.randomUUID().toString();
        Instant accessTokenExpires = now.plus(10, ChronoUnit.MINUTES);
        Instant refreshTokenExpires = now.plus(24, ChronoUnit.HOURS);

        Token newAccessTokenToken = new Token(newAccessToken, userId, TokenType.ACCESS_TOKEN, now, accessTokenExpires);
        Token newRefreshTokenToken = new Token(newRefreshToken, userId, TokenType.REFRESH_TOKEN, now, refreshTokenExpires);

        tokenRepository.save(newAccessTokenToken);
        tokenRepository.save(newRefreshTokenToken);

        return new RenewResponse(newAccessToken, newRefreshToken, userId);
    }

    /**
     * Validate and consume a one-time token
     */
    @Transactional
    public TokenValidationResult validateOneTimeToken(String tokenValue) {
        Instant now = Instant.now();

        // Find token
        Token token = tokenRepository.findByTokenValue(tokenValue)
            .orElseThrow(() -> new RuntimeException("Token not found"));

        // Check type
        if (token.getTokenType() != TokenType.ONE_TIME_TOKEN) {
            throw new RuntimeException("Invalid token type");
        }

        // Check if already consumed
        if (token.isConsumed()) {
            throw new RuntimeException("Token already consumed");
        }

        // Check if expired
        if (token.getExpiresAt().isBefore(now)) {
            throw new RuntimeException("Token expired");
        }

        // Check if revoked
        if (token.isRevoked()) {
            throw new RuntimeException("Token revoked");
        }

        // Atomically mark as consumed
        tokenRepository.consumeTokenByValue(tokenValue);

        // Return success
        return new TokenValidationResult(true, token.getUserId());
    }

    /**
     * Logout - revoke all tokens for user
     */
    @Transactional
    public void logout(String accessTokenValue) {
        // Find the access token to get user ID
        Token accessToken = tokenRepository.findByTokenValue(accessTokenValue)
            .orElseThrow(() -> new RuntimeException("Access token not found"));

        String userId = accessToken.getUserId();

        // Revoke all tokens for this user
        List<Token> userTokens = tokenRepository.findByUserId(userId);
        for (Token token : userTokens) {
            token.setRevoked(true);
        }
        tokenRepository.saveAll(userTokens);
    }
}
EOF"}

