package com.auth.server.controller;

import com.auth.server.model.LoginResponse;
import com.auth.server.model.RenewResponse;
import com.auth.server.model.TokenValidationResult;
import com.auth.server.service.AuthService;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    /**
     * POST /api/auth/login
     * Issues three tokens: Access Token, Refresh Token (cookie), One-Time Token
     */
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody(required = false) Map<String, String> credentials, 
                                   HttpServletResponse response) {
        // Validate request body
        if (credentials == null || !credentials.containsKey("username") || 
            !credentials.containsKey("password") || 
            credentials.get("username") == null || credentials.get("username").isEmpty() ||
            credentials.get("password") == null || credentials.get("password").isEmpty()) {
            return ResponseEntity.badRequest().body(Map.of(
                "error", "Username and password are required and must be non-empty"
            ));
        }

        String username = credentials.get("username");
        String password = credentials.get("password");

        try {
            LoginResponse loginResponse = authService.login(username, password);

            // Set Refresh Token as HTTP-only cookie
            Cookie refreshTokenCookie = new Cookie("refreshToken", loginResponse.getRefreshToken());
            refreshTokenCookie.setHttpOnly(true);
            refreshTokenCookie.setMaxAge(86400); // 24 hours in seconds
            refreshTokenCookie.setPath("/");
            response.addCookie(refreshTokenCookie);

            // Build response
            Map<String, String> body = new HashMap<>();
            body.put("accessToken", loginResponse.getAccessToken());
            body.put("oneTimeToken", loginResponse.getOneTimeToken());

            return ResponseEntity.ok(body);
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of(
                "error", e.getMessage()
            ));
        }
    }

    /**
     * POST /api/auth/renew
     * Renew access token using refresh token from Cookie (preferred) or Header
     */
    @PostMapping("/renew")
    public ResponseEntity<?> renew(HttpServletRequest request, HttpServletResponse response) {
        String refreshTokenValue = null;

        // Check Cookie first (takes precedence)
        Cookie[] cookies = request.getCookies();
        if (cookies != null) {
            for (Cookie cookie : cookies) {
                if ("refreshToken".equals(cookie.getName())) {
                    refreshTokenValue = cookie.getValue();
                    break;
                }
            }
        }

        // If not in cookie, check Header
        if (refreshTokenValue == null) {
            refreshTokenValue = request.getHeader("refreshToken");
        }

        if (refreshTokenValue == null || refreshTokenValue.isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of(
                "error", "Refresh token is required (in cookie or header)"
            ));
        }

        try {
            RenewResponse renewResponse = authService.renew(refreshTokenValue);

            // Set new Refresh Token as HTTP-only cookie
            Cookie newRefreshTokenCookie = new Cookie("refreshToken", renewResponse.getRefreshToken());
            newRefreshTokenCookie.setHttpOnly(true);
            newRefreshTokenCookie.setMaxAge(86400);
            newRefreshTokenCookie.setPath("/");
            response.addCookie(newRefreshTokenCookie);

            Map<String, String> body = new HashMap<>();
            body.put("accessToken", renewResponse.getAccessToken());

            return ResponseEntity.ok(body);
        } catch (RuntimeException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of(
                "error", e.getMessage()
            ));
        }
    }

    /**
     * POST /api/auth/validate-token
     * Validate and consume a one-time token
     */
    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody(required = false) Map<String, String> request) {
        if (request == null || !request.containsKey("token") || request.get("token") == null) {
            return ResponseEntity.badRequest().body(Map.of(
                "valid", false,
                "message", "Token is required"
            ));
        }

        String tokenValue = request.get("token");

        try {
            TokenValidationResult result = authService.validateOneTimeToken(tokenValue);
            Map<String, Object> responseMap = new HashMap<>();
            responseMap.put("valid", true);
            responseMap.put("message", "Token validated successfully");
            return ResponseEntity.ok(responseMap);
        } catch (RuntimeException e) {
            Map<String, Object> errorResponse = new HashMap<>();
            errorResponse.put("valid", false);
            errorResponse.put("message", e.getMessage());
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(errorResponse);
        }
    }

    /**
     * POST /api/auth/logout
     * Invalidate all tokens for the authenticated user
     */
    @PostMapping("/logout")
    public ResponseEntity<?> logout(HttpServletRequest request) {
        String authHeader = request.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of(
                "error", "Authorization header required with Bearer token"
            ));
        }

        String accessToken = authHeader.substring(7); // Remove "Bearer " prefix

        if (accessToken == null || accessToken.isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of(
                "error", "Access token is required"
            ));
        }

        try {
            authService.logout(accessToken);
            return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
        } catch (RuntimeException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of(
                "error", e.getMessage()
            ));
        }
    }
}
